var oc$ = f.getItem('status'), vc, ic;
if (!f._$handleStatusCancel) {
  for (ic = oc$.options.length - 1; ic >= 0; ic--) {
    vc = oc$.options[ic];
    if (vc.value == '9') {
      f._$handleStatusCancel = [vc];
      break;
    }
  }
}

if (f._action != 'View') {
  if (oc$.value == '9') oc$.value = f.grid._dvHandle;
  for (ic = oc$.options.length - 1; ic >= 0; ic--) if (oc$.options[ic].value == '9') {
    oc$.remove(ic);
    f._$wasRemovedCancel = true;
    break;
  }
} else f._$wasRemovedCancel = null;

var or$ = f.getItem('status'), vr, ir;
if (!f._$handleStatusRemove) {
  for (ir = or$.options.length - 1; ir >= 0; ir--) {
    vr = or$.options[ir];
    if (vr.value == '*') {
      f._$handleStatusRemove = [vr];
      break;
    }
  }
}

if (f._action != 'View') {
  if (or$.value == '*') or$.value = f.grid._dvHandle;
  for (ir = or$.options.length - 1; ir >= 0; ir--) if (or$.options[ir].value == '*') {
    or$.remove(ir);
    f._$wasRemovedDeletion = true;
    break;
  }
} else f._$wasRemovedDeletion = null;
